/* Builds v6/vendor/model-icons/icons.js from map.json and the SVGO-optimised svg/*.svg (file:// pages cannot fetch).
   Usage: node vendor/model-icons/build.js (from the mock's root). No dependencies. SVGO runs before, on new icons only.
   Brand fills under the floor get a light-dark() lightness lift (map.json brand). */
const fs = require('fs'), path = require('path');
const V6 = process.argv[2] || path.join(__dirname, '../..');
const DIR = path.join(V6, 'vendor/model-icons');
const map = JSON.parse(fs.readFileSync(path.join(DIR, 'map.json'), 'utf8'));
const NAMED = { gold: '#ffd700', white: '#ffffff', black: '#000000' };

/* sRGB <-> OKLab */
const toLin = (c) => (c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4));
const toGam = (c) => (c <= 0.0031308 ? 12.92 * c : 1.055 * Math.pow(c, 1 / 2.4) - 0.055);
const hex2rgb = (h) => { h = h.replace('#', ''); if (h.length === 3) h = h.replace(/./g, '$&$&'); return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16) / 255); };
const rgb2hex = (c) => '#' + c.map((v) => Math.round(Math.min(1, Math.max(0, v)) * 255).toString(16).padStart(2, '0')).join('');
function rgb2lab(c) {
  const [r, g, b] = c.map(toLin);
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  return [0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s, 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s, 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s];
}
function lab2rgb([L, a, b]) {
  const l = Math.pow(L + 0.3963377774 * a + 0.2158037573 * b, 3), m = Math.pow(L - 0.1055613458 * a - 0.0638541728 * b, 3), s = Math.pow(L - 0.0894841775 * a - 1.291485548 * b, 3);
  return [4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s, -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s, -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s].map(toGam);
}
const inGamut = (c) => c.every((v) => v >= -1e-4 && v <= 1 + 1e-4);
const lum = (c) => { const [r, g, b] = c.map((v) => toLin(Math.min(1, Math.max(0, v)))); return 0.2126 * r + 0.7152 * g + 0.0722 * b; };
const contrast = (a, b) => { const x = lum(a), y = lum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
/* keep hue, move lightness (shrinking chroma only when the colour would leave sRGB) until the floor is met */
function lift(hex, ground, floor) {
  const c = hex2rgb(hex), g = hex2rgb(ground);
  if (contrast(c, g) >= floor) return null;
  const [L, a, b] = rgb2lab(c), up = lum(g) < 0.18;
  const at = (L2) => { let k = 1, rgb = lab2rgb([L2, a, b]); while (!inGamut(rgb) && k > 0) { k -= 0.02; rgb = lab2rgb([L2, a * k, b * k]); } return rgb; };
  let lo = L, hi = up ? 1 : 0;
  for (let i = 0; i < 40; i++) { const mid = (lo + hi) / 2; if (contrast(at(mid), g) >= floor + 0.02) hi = mid; else lo = mid; }
  return rgb2hex(at(hi));
}

const read = (n) => { const f = path.join(DIR, 'svg', n + '.svg'); return fs.existsSync(f) ? fs.readFileSync(f, 'utf8').trim() : null; };
function split(svg) {
  const m = /^<svg([^>]*)>([\s\S]*)<\/svg>$/.exec(svg);
  if (!m) throw new Error('not an svg');
  const attrs = m[1].replace(/\s+xmlns="[^"]*"/, '').replace(/\s+viewBox="[^"]*"/, '');
  const vb = (/viewBox="([^"]*)"/.exec(m[1]) || [0, '0 0 24 24'])[1];
  return { viewBox: vb, attrs: attrs.trim(), body: m[2] };
}
const report = [];
function brandify(icon, svg) {
  const { floor, grounds } = map.brand;
  return svg.replace(/(fill|stop-color)="(#[0-9a-fA-F]{3,6}|[a-z]+)"/g, (all, prop, v) => {
    const hex = v.startsWith('#') ? v.toLowerCase() : NAMED[v];
    if (!hex) return all;                       /* currentColor, none, url(#…) */
    const dk = lift(hex, grounds.dark, floor), lt = lift(hex, grounds.light, floor);
    if (!dk && !lt) return prop + '="' + hex + '"';
    report.push(icon + ' ' + hex + ' dark→' + (dk || '=') + ' light→' + (lt || '='));
    return prop + '="' + hex + '" style="' + prop + ':light-dark(' + (lt || hex) + ',' + (dk || hex) + ')"';
  });
}

const used = new Set([...map.families, ...map.served, map.fallback].map((f) => f.icon));
const icons = {};
for (const id of used) {
  const mono = read(id), color = read(id + '-color');
  if (!mono) throw new Error('missing svg/' + id + '.svg');
  icons[id] = { mono: split(mono) };
  if (color) icons[id].color = split(brandify(id, color));
}
const out = '/* generated by vendor/model-icons/build.js from vendor/model-icons/map.json and svg/*.svg: do not edit by hand.\n' +
  '   Icons: @lobehub/icons-static-svg 1.104.0 (MIT), SVGO 3.3.2; generic.svg is boopis\'s own. See NOTICE. */\n' +
  'window.HX_MODEL_ICONS = ' + JSON.stringify({ map, icons }) + ';\n';
fs.writeFileSync(path.join(DIR, 'icons.js'), out);
console.log(report.join('\n'));
console.log('icons.js', out.length, 'bytes,', Object.keys(icons).length, 'icons');
